package okay.compress

/** frames pyarrow wrote (ZSTD at levels 3 and 19, the LZ4 frame format),
 * so the decoders meet a real producer on EVERY platform, not only where a
 * python runs */
object Fixtures:
  // generated once by pyarrow 25.0.1: the frames are pyarrow's, the inputs are rebuilt in `input`
  val zstd_text_3 = "KLUv/WDAKh0CAHQDdGhlIHF1aWNrIGJyb3duIGZveCBqdW1wcyBvdmVyIHRoZSBsYXp5IGRvZzsg0YfQsNC5IOKYlQIAgWsrDo6FCQU="
  val zstd_text_19 = "KLUv/WDAKgUCAEQDdGhlIHF1aWNrIGJyb3duIGZveCBqdW1wcyBvdmVyIGxhenkgZG9nOyDRh9Cw0Lkg4piVIAIAC9dWzBascgI="
  val lz4_text = "BCJNGGBAgnAAAADwEHRoZSBxdWljayBicm93biBmb3gganVtcHMgb3ZlciAfAPEFbGF6eSBkb2c7INGH0LDQuSDimJUZAA84AP////////////////////////////////////////////////////////+XUCDimJUgAAAAAA=="
  val zstd_numbers_3 = ""
  val zstd_numbers_19 = ""
  val lz4_numbers = ""

  def input(name: String): Array[Byte] = name match
    case "text" => ("the quick brown fox jumps over the lazy dog; чай ☕ " * 200).getBytes("UTF-8")
    case _ => (0 until 600).map(i => s"$i,${i * 7 % 1000},row$i\n").mkString.getBytes("UTF-8")

  val frames: Vector[(String, String, String)] = Vector(
    ("zstd", "text", zstd_text_3), ("zstd", "text", zstd_text_19),
    ("zstd", "numbers", zstd_numbers_3), ("zstd", "numbers", zstd_numbers_19),
    ("lz4", "text", lz4_text), ("lz4", "numbers", lz4_numbers))
